105			if p := strings.TrimPrefix(subpath, "/"); strings.Contains(p, "/") {
106				validator.Push(fmt.Errorf(errFmtServerPathNotEndForwardSlash, subpath))
107			} else if !utils.IsStringAlphaNumeric(p) {
108				validator.Push(fmt.Errorf(errFmtServerPathAlphaNumeric, subpath))
109			}
110		}
111	
112		if config.Server.Address.IsUnixDomainSocket() || config.Server.Address.IsFileDescriptor() {
113			config.Server.DisableHealthcheck = true
114		}
